  const loan = sampleLoan({
    id: 'loan_1',
    item: BOOK,
    member: ADA,
    checkedOutOn: '2026-10-29',
    dueOn: '2026-11-19',
  });
  const result = renewLoan(sampleStore({ loans: [loan] }), { loanId: 'loan_1', today: TODAY });
  assert.deepEqual(result, { ok: false, reason: 'overdue' });
});
